bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';
import {readFileSync} from 'node:fs';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try {
 const q=await pool.query("SELECT s.state,s.updated_at FROM videobot_creator_sessions s JOIN videobot_listings l ON l.seller_user_id=s.owner_user_id WHERE l.listing_id=$1",['v26nov24invoice']);
 if(q.rows.length!==1)process.exitCode=80;
 else {
  const {state,updated_at}=q.rows[0];
  const d=state.draft;
  console.log(JSON.stringify({screen:state.screen,mode:d?.mode,updated_at,hasMain:!!d?.paidVideo?.fileId,hasSample:!!d?.sample?.fileId,sampleDuration:d?.sample?.durationSeconds??null,hasFirstThumbnail:!!d?.thumbnail?.fileId,hasSecondThumbnail:!!d?.thumbnail?.secondFileId}));
  if(!d?.paidVideo?.fileId)process.exitCode=81;
  else if(!d.sample?.fileId)process.exitCode=82;
  else if(!d.thumbnail?.secondFileId)process.exitCode=83;
 }
} finally {await pool.end();}
JS
